    translation: '水上、陆地上各种草本木本的花，值得喜爱的有很多。晋朝的陶渊明唯独喜爱菊花。从唐代以来，世人非常喜欢牡丹。我唯独喜爱莲花，它从淤泥中长出来，却不受到污染；在清水里洗涤过，却不显得妖媚；它的茎中间贯通，外形挺直，不生枝蔓，不长枝节；香气传播得越远越清幽；笔直洁净地立在那里，只能在远处观赏，却不能靠近轻易地玩弄它。我认为，菊花是花中的隐士；牡丹，是花中的富贵者；莲花，是花中的君子。唉！对于菊花的喜爱，在陶渊明以后很少听到了。对于莲花的喜爱，和我一样的还有谁呢？对于牡丹的喜爱，人该是很多了！',
