    translation: '元丰六年十月十二日夜晚，我脱了衣服打算睡觉，这时月光照入门中，我高兴地起来走动。想到没有和我一起游乐的人，于是到承天寺寻找张怀民。张怀民也没有睡觉，我们一起在庭院中散步。月光照在庭院里像积满了清水一样澄澈透明，水中的水草纵横交错，原来是竹子和柏树的影子。哪一个夜晚没有月光？哪个地方没有竹子和柏树？只是缺少像我们两个这样有闲情逸致的人罢了。',
