    translation: '八月里秋深，狂风怒号，卷走了我屋顶上好几层茅草。茅草乱飞，渡过浣花溪，散落在对岸江边。飞得高的茅草挂在高树梢上，飞得低的飘飘洒洒沉落到池塘和洼地里。南村的一群儿童欺负我年老没力气，竟忍心这样当面做"贼"抢东西，毫无顾忌地抱着茅草跑进竹林去了。我嘴唇干燥也喝止不住，回来后拄着拐杖独自叹息。不一会儿风停了，云黑得像墨一样，秋天的天空阴沉迷蒙渐渐黑下来。布被子盖了多年又冷又硬像铁块似的，孩子睡相不好把被里蹬破了。屋顶漏雨，床头没有一点干燥的地方，雨点像下垂的麻线一样密集不停。自从安史之乱后，我睡眠的时间很少，长夜漫漫，屋漏床湿，怎能挨到天亮！如何能得到千万间宽敞高大的房子，普遍地庇护天下间贫寒的读书人，让他们都开颜欢笑！房子不为风雨所动摇，安稳得像山一样。唉！什么时候眼前出现这样高耸的房屋，即使唯独我的茅屋被打破，自己受冻而死也心甘情愿！',
