    translation: '一个屠户傍晚回家，担子里的肉已经卖完，只剩下一些骨头。路上遇到两只狼，紧跟着走了很远。屠户害怕了，把骨头投给狼。一只狼得到骨头停下了，另一只狼仍然跟从。又投骨头，后一只狼停下了，前一只狼又追上来。骨头已经投完了，但两只狼像原来一样一起追赶。屠户非常困窘，害怕前后受到两只狼的夹击。他看见野地里有个打麦场，场主人把柴草堆积在打麦场里，覆盖成小山似的。屠户于是跑过去倚靠在柴草堆下面，卸下担子拿起屠刀。狼不敢上前，瞪眼朝着屠户。一会儿，一只狼径直走开，另一只狼像狗似的蹲坐在前面。过了很久，那只狼的眼睛似乎闭上了，神情悠闲得很。屠户突然跳起来，用刀劈狼的脑袋，又连砍几刀把狼杀死了。刚想走，转身看柴草堆后面，只见另一只狼正在柴草堆里打洞，企图从通道进入来攻击屠户的背后。狼的身子已经钻进一半，只有屁股和尾巴露在外面。屠户从后面砍断了狼的大腿，也把这只狼杀死了。这才明白前面的那只狼假装睡觉，原来是用来诱惑敌方的。狼也太狡猾了，可是一会儿两只狼都被杀死了，禽兽的欺骗手段能有多少呢？只是增加笑料罢了。',
