    translation: '叹息声一声连着一声，木兰对着房门在织布。听不见织布机发出的声音，只听见姑娘在叹息。问姑娘在想什么，问姑娘在惦记什么。姑娘也没有想什么，姑娘也没有惦记什么。昨夜看见征兵的文书，可汗在举行大规模的抽丁。征兵的名册很多卷，卷卷上面都有父亲的名字。父亲没有大儿子，木兰没有哥哥，愿意为此去买马鞍和马匹，从此代替父亲出征。到东市买了骏马，到西市买了马鞍和鞯垫，到南市买了马缰绳，到北市买了长鞭。早晨辞别父母离开家，晚上宿营在黄河边，听不见父母呼唤女儿的声音，只能听到黄河水奔腾流淌的声音。早晨辞别黄河边，晚上到达黑山头，听不见父母呼唤女儿的声音，只能听到燕山胡人的战马嘶鸣的声音。不远万里奔赴战场，翻越重重山峰就像飞起来那样迅速。北方的寒气传送着打更的声音，清冷的月光照射着铁打的铠甲。将士们身经百战，有的战死沙场，有的多年后重返故乡。归来朝见天子，天子坐在明堂上。记功很多次，赏赐了很多财物。可汗问木兰想要什么，木兰不愿意做尚书郎，只希望骑上一匹千里马，送木兰回故乡。父母听说女儿回来了，互相搀扶着到城外迎接；姐姐听说妹妹回来了，对着门户梳妆打扮起来；弟弟听说姐姐回来了，霍霍地磨刀准备杀猪宰羊。打开我东边阁楼的门，坐进我西边阁楼的床，脱下我打仗时穿的战袍，穿上我以前女孩子的衣裳。对着窗户梳理美丽的头发，对着镜子在脸上贴上装饰的花黄。走出门去看看同伍的士兵，伙伴们都很吃惊：同行战斗了十二年，竟然不知道木兰是女孩子。',
