    translation: '康肃公陈尧咨擅长射箭，当时没有人能和他相比，他也因此自夸。有一次他在自家花园里射箭，有个卖油的老翁放下担子站在一旁，斜着眼看了很久没有离开。看到他射出的箭十枝能中八九枝，只是微微点了点头。康肃公问道："你也懂得射箭吗？我射箭的本领不是很精妙吗？"老翁说："没有别的奥妙，只是手法熟练罢了。"康肃公气愤地说："你怎么敢轻视我射箭的本领！"老翁说："凭我倒油的经验知道这个道理。"于是拿出一个葫芦放在地上，用一枚铜钱盖住葫芦口，慢慢地用勺子舀油滴入，油从铜钱的方孔中注入，而铜钱却没有沾湿。老翁接着说："我也没有什么别的奥妙，只是手法熟练罢了。"康肃公笑着把他打发走了。',
