    translation: '在三峡七百里之间，两岸都是相连的山，全然没有中断的地方。层层的悬崖，排排的峭壁，遮蔽了天空和太阳。如果不是正午就看不到太阳，如果不是半夜就看不到月亮。到了夏天江水漫上山陵，上行和下行的航路都被阻断。有时皇帝的命令必须紧急传达，这时只要早晨从白帝城出发，傍晚就到了江陵，这中间有一千二百里，即使骑上快马驾着风，也没有这么快。春冬两季的时候，白色的急流回旋着清波，碧绿的深潭倒映着各种景物的影子。极高的山峰上生长着许多奇形怪状的柏树，悬挂着的泉水瀑布在山峰间飞流冲荡，水清树荣山高草盛，确实有很多趣味。每逢初晴的日子或者结霜的早晨，树林和山涧一片清凉和寂静，经常有高处的猿猴拉长声音啼叫，声音连续不断，非常凄凉怪异，空旷的山谷传来回声，悲哀婉转很久才消失。所以渔人唱道："巴东三峡巫峡长，猿鸣三声泪沾裳。"',
