    translation: '风停雾散，天空和群山是同一种颜色。我乘船随江流飘荡，任凭它向东或向西。从富阳到桐庐大约一百多里，奇异的山水，天下独一无二。江水都是浅青色的，千丈之深也能看见水底。游动的鱼儿和细小的石头，可以直接看清楚，毫无障碍。湍急的水流比飞箭还要快，汹涌的波浪就像奔腾的骏马。两岸的高山上，都生长着耐寒的树木，这些山峦凭借高峻的地势争相向上，仿佛在比高远，笔直地向上直插云天，形成无数山峰。泉水冲击着石头，发出泠泠的清越声响；美丽的鸟儿互相和鸣，嘤嘤的声音十分和谐。蝉不断地鸣叫着，猿也不断地啼叫着。那些像鸢鸟一样飞上天空的人，看到这些雄奇的山峰就会平息追名逐利的心；那些治理政务的人，看到这些幽美的山谷就会流连忘返。横斜的树枝在上边遮蔽着，即使在白天也像黄昏时那样昏暗；稀疏的枝条互相掩映，有时还能见到阳光。',
