    translation: '太行、王屋两座山，方圆七百里，高七八千丈，本来在冀州的南面，黄河的北面。北山下面有个名叫愚公的人，年纪将近九十岁了，面对着山居住。他苦于大山阻挡在北面，出来进去都要绕远路，于是集合全家人来商量说："我跟你们尽全力铲平险峻的大山，使道路一直通到豫州的南部，到达汉水南岸，可以吗？"大家纷纷表示赞同。他的妻子提出疑问说："凭你的力气，连魁父这座小山都不能削平，又能把太行、王屋这两座山怎么样呢？况且把挖下来的泥土石头放到哪里去呢？"众人纷纷说："把它们扔到渤海的边上，隐土的北面。"于是愚公率领儿孙中能挑担子的三个人上了山，凿石头，挖泥土，用簸箕和土筐把土石运到渤海的边上。邻居京城氏的寡妇有个孤儿，刚刚七八岁，也蹦蹦跳跳地去帮助他们。冬夏换季，才能往返一次。河湾上的智叟讥笑愚公，阻止他干这件事，说："你太不聪明了！就凭你风烛残年的余力，连山上的一根草木都毁不了，又能把泥土石头怎么样呢？"北山愚公长叹一声说："你思想顽固，顽固到了不可改变的地步，连孤儿寡妇都不如。即使我死了，还有儿子在呀；儿子又生孙子，孙子又生儿子；儿子又有儿子，儿子又有孙子；子子孙孙无穷无尽，可是这山却不会再增高加大了，还愁什么挖不平呢？"河曲智叟无话可答。手里拿着蛇的山神听说了这件事，怕他不停地挖下去，向天帝报告了。天帝被愚公的诚心感动，命令大力神夸娥氏的两个儿子背走了这两座山，一座放在朔方的东部，一座放在雍州的南部。从此以后，冀州的南部直到汉水南岸，再也没有山冈阻隔了。',
