    translation: '汉文帝后元六年，匈奴大规模侵入汉朝边境。于是朝廷任命宗正刘礼为将军，驻军在霸上；任命祝兹侯徐厉为将军，驻军在棘门；任命河内郡太守周亚夫为将军，驻军在细柳：来防备匈奴入侵。皇上亲自去慰劳军队。到了霸上和棘门的军营，长驱直入，将军及其属下都骑着马迎送。不久来到了细柳军营，只见官兵都披戴铠甲，兵器锋利，弓弩拉开，弓弦拉满。天子的先导人员到了，不能进入营门。先导说："天子将要到了！"军门都尉说："将军有令：军中只听从将军的命令，不听从天子的诏令。"过了不久，皇上到了，也不能进入。于是皇上就派使者拿了符节下诏令给将军："我要进去慰劳军队。"周亚夫这才传令打开营门。守营门的军官对随从的车马说："将军规定，军营中不得驱车快跑。"于是天子就控制住车马缓步前行。到了营中，将军周亚夫手持兵器拱手行礼说："穿戴铠甲头盔的将士不能跪拜，请允许我用军礼参见陛下。"天子被感动了，脸上的神情也改变了，俯身扶着车前的横木表示敬意。派人致谢说："皇帝敬重地慰劳将军。"劳军礼仪完毕后辞去。出了军门后，群臣都很惊讶。文帝说："啊，这才是真正的将军啊！先前霸上、棘门军营，简直像儿戏一样，他们的将领是完全可能被偷袭而俘虏的。至于周亚夫，哪里能够侵犯呢！"称赞了他很久。',
