    translation: '从小山向西走一百二十步，隔着竹林，听到了水声，好像佩环碰撞的声音，心里很是高兴。砍伐竹子开辟道路，往下看见一个小潭，水格外清凉。整块石头作为潭底，靠近岸边，石底翻卷出水面，成为坻、屿、嵁、岩等各种不同的形状。青葱的树木和翠绿的藤蔓，蒙盖缠绕摇曳牵连，参差不齐随风飘动。潭中的鱼大约有一百来条，都好像在空中游动，没有什么依傍的，阳光直照到水底，鱼的影子映在石上。呆呆地停在那里一动不动，忽然间向远处游去，来来往往轻快敏捷，好像跟游玩的人逗乐。向小石潭的西南方看去，溪水像北斗星那样曲折，像蛇那样蜿蜒前行，时隐时现。溪岸的形状像狗的牙齿那样参差不齐，不能知道它的源头在哪里。坐在小石潭上，四面被竹子和树木围绕着，寂静寥落无人迹，使人感到心神凄凉寒气透骨，幽静得使人感到忧伤。因为这里的环境太凄清了，不可以久留，就题字离去。同游的人有吴武陵、龚古和我的弟弟宗玄。跟随着来的人有姓崔的两个年轻人，一个叫恕己，一个叫奉壹。',
