    translation: '明代有个手艺奇妙精巧的人叫王叔远，能够用直径一寸的木头，雕刻宫室、器具、人物，以及飞禽走兽、树木石头，无不按照材料的形状来雕刻，各自具有情态。他曾经赠送给我一个桃核刻成的船，刻的是苏轼乘船游赤壁。船从头到尾长约八分多一点，大约有两个黄米粒那么高。中间高而宽敞的部分是船舱，用箬竹叶做成的船篷覆盖着它。旁边开着小窗，左右各四扇，一共八扇。打开窗户看，雕刻着花纹的栏杆左右相对。关上窗户，就看到右边刻着"山高月小，水落石出"，左边刻着"清风徐来，水波不兴"，用石青涂在字的凹处。船头坐着三个人，中间戴着高帽子并且胡须很多的是苏东坡，佛印在右边，黄鲁直在左边。苏、黄一起看一幅书画横幅。苏东坡右手拿着卷端，左手抚着鲁直的背。鲁直左手拿着卷末，右手指着手卷，好像在说什么话。东坡露出右脚，鲁直露出左脚，各自略微侧着身子，他们互相靠近的两膝，各自隐藏在手卷下面的衣褶里。佛印极像弥勒菩萨，敞胸露乳，抬头仰望，神情跟苏、黄不一样。他平放右膝，弯着右臂支撑在船上，而竖起左膝，左臂挂着念珠靠在左膝上——念珠可以清清楚楚地数出来。船尾横放着一支桨。桨的左右各有一个船夫。在右边的人梳着椎形发髻仰着脸，左手靠着一根横木，右手扳着右脚趾，好像在大声呼叫的样子。在左边的人右手拿着蒲葵扇，左手抚着炉子，炉子上面有个壶，那个人眼光正视着茶炉神色平静，好像在听茶水烧开了没有的样子。这只船的底部比较平坦，就在上面刻着名字，文字是"天启壬戌秋日，虞山王毅叔远甫刻"，笔画细得像蚊子的脚，一钩一画都清清楚楚，颜色是黑的。还刻着一个篆字图章，文字是"初平山人"，颜色是红的。总计一条船上，刻了五个人；八扇小窗；箬竹叶做的船篷、船桨、炉子、茶壶、手卷、念珠各一件；对联、题名和篆文，刻的字共三十四个。可是计算它的长度还不满一寸。大概是挑选了长而窄的桃核来雕刻的。嘻，这技艺也真神奇啊！',
