    translation: '庄子和惠子在濠水的桥上散步。庄子说："鯈鱼在河水中游得多么悠闲自得，这是鱼的快乐啊。"惠子说："你不是鱼，怎么知道鱼的快乐呢？"庄子说："你不是我，怎么知道我不知道鱼的快乐呢？"惠子说："我不是你，固然不知道你；你本来就不是鱼，你不知道鱼的快乐，这是完全可以确定的！"庄子说："请追溯话题本源。你说\'你怎么知道鱼的快乐\'的话，说明你已经知道我知道鱼的快乐才问我的，我是在濠水的桥上知道的。"',
