    translation: '崇祯五年十二月，我住在西湖边。大雪下了三天，湖中行人、飞鸟的声音都消失了。这天晚上八点左右，我撑着一只小船，裹着裘皮衣服，带着火炉，独自前往湖心亭看雪。冰花一片弥漫，天与云与山与水，上下全白了。湖上的影子，只有西湖长堤一道痕迹、湖心亭一个小点，以及我的小船一片草叶和船中两三个人影罢了。到了亭上，有两个人铺着毡子对坐，一个童子在烧酒，炉子正烧得沸腾。他们看见我非常高兴，说："湖中怎么还有这样的人！"拉着我一起喝酒。我痛饮了三大杯酒然后告别。问他们的姓名，说是金陵人，在此地客居。等到下了船，船夫嘟囔道："别说相公痴，还有比相公更痴的人呢！"',
