    translation: '鱼，是我所想要的；熊掌，也是我所想要的。如果两者不能同时得到，就舍弃鱼而选取熊掌。生命，是我所想要的；道义，也是我所想要的。如果两者不能同时得到，就舍弃生命而选取道义。生命也是我所想要的，但想要的还有比生命更重要的东西，所以不做苟且偷生的事；死亡也是我所厌恶的，但厌恶的还有比死亡更严重的事，所以有的祸患就不躲避。如果人们想要的东西没有比生命更重要的，那么凡是可以保全生命的方法有什么不可用的呢？如果人们厌恶的东西没有比死亡更严重的，那么凡是可以躲避祸患的方法有什么不可以做的呢？由此看来，可以保全生命却有人不去做，可以躲避祸患却有人不去做。由此可见，想要的东西有比生命更重要的，厌恶的东西有比死亡更严重的。不只是贤人有这种心，人人都有，只是贤人能够不丧失罢了。一筐饭，一碗汤，得到它就能活命，得不到就会饿死。但如果轻蔑地吆喝着给人吃，过路的人不会接受；用脚踩踏过再给人吃，连乞丐都不屑一顾。优厚的俸禄如果不辨别是否合乎礼义就接受了，那优厚的俸禄对我有什么益处呢！是为了住宅的华丽、妻妾的侍奉、所认识的贫困之人感激我吗？从前宁可死也不愿接受的，现在却为了住宅的华丽而接受了；从前宁可死也不愿接受的，现在却为了妻妾的侍奉而接受了；从前宁可死也不愿接受的，现在却为了所认识的贫困之人感激我而接受了：这些不也应该停止了吗？这就叫做丧失了本来的良心。',
