    translation: '秦王派人告诉安陵君说："我想用五百里的土地来交换安陵，安陵君一定要答应我！"安陵君说："大王施予恩惠，用大面积的土地来交换小面积的土地，很好；虽然如此，但我从先王那里接受了封地，愿意始终守卫它，不敢交换！"秦王不高兴了。安陵君因此派唐雎出使秦国。秦王对唐雎说："我用五百里的土地来交换安陵，安陵君不听从我，为什么呢？况且魏国灭亡而韩国也灭亡了，安陵君却凭着五十里的土地幸存下来，只是因为有先生啊。现在我用十倍的土地，让安陵君扩大领土，但安陵君违抗我，是轻视我吗？"唐雎回答说："不，不是这样的。安陵君从先王那里接受了封地并守卫它，即使是千里的土地也不敢交换，何况只是五百里呢？"秦王勃然大怒，对唐雎说："您也曾听说过天子发怒吗？"唐雎回答说："我未曾听说过。"秦王说："天子发怒，伏尸百万，流血千里。"唐雎说："大王曾经听说过平民发怒吗？"秦王说："平民发怒，也不过是摘掉帽子光着脚，用头撞地罢了。"唐雎说："这是平庸之人的发怒，不是有胆识之士的发怒。专诸刺杀吴王僚的时候，彗星的尾巴扫过月亮；聂政刺杀韩傀的时候，一道白虹直冲太阳；要离刺杀庆忌的时候，苍鹰扑击到宫殿上。这三个人，都是出身平民的有识之士，满怀怒气还未发作出来，上天就降示了征兆，现在加上我，将有四个人了。如果有胆识之士一定要发怒，就要让两个人的尸体倒下，血流五步远，天下人都要穿白色丧服，今天就是这样。"于是拔出宝剑站了起来。秦王变了脸色，直身跪着向唐雎道歉说："先生请坐！怎么会到这种地步！我明白了：韩国、魏国灭亡了，而安陵国却凭着五十里的土地幸存下来，只是因为有先生啊。"',
