    translation: '鲁庄公十年的春天，齐国军队攻打鲁国。鲁庄公将要迎战，曹刿请求拜见。他的同乡说："当权者会谋划这件事的，你又何必参与呢？"曹刿说："当权者目光短浅，不能深谋远虑。"于是入朝拜见。曹刿问："您凭什么条件作战？"鲁庄公说："衣食这类养生的东西，不敢独自享受，一定分给别人。"曹刿回答说："小恩小惠不能遍及百姓，百姓是不会跟从您的。"鲁庄公说："祭祀用的牛羊玉帛，不敢虚报，一定对神诚实。"曹刿回答说："这点小信用不能使神信服，神是不会保佑您的。"鲁庄公说："大大小小的案件，即使不能一一明察，一定根据实情处理。"曹刿回答说："这是尽了本职的一类事情，可以凭这个条件打一仗。如果作战，就请允许我跟随着去。"鲁庄公和他同乘一辆战车，在长勺交战。鲁庄公将要击鼓进军。曹刿说："不行。"齐军击鼓三次后，曹刿说："可以了。"齐军大败。鲁庄公将要追击齐军。曹刿说："不行。"他走下战车查看齐军的车辙，登上车前横木眺望齐军，说："可以了。"于是追击齐军。战胜后，鲁庄公问其中原因。曹刿回答说："作战，靠的是勇气。第一次击鼓能够振作勇气，第二次击鼓勇气就衰退了，第三次击鼓勇气就耗尽了。他们的勇气耗尽了而我军勇气正旺盛，所以战胜了他们。大国是难以揣测的，恐怕有埋伏。我看到他们的车辙混乱，望见他们的旗帜倒下了，所以才追击他们。"',
