    translation: '邹忌身高八尺多，容貌光艳美丽。早晨穿戴好衣帽，照着镜子，对他的妻子说："我与城北徐公相比谁更美丽？"他的妻子说："您美极了，徐公怎么能比得上您呢！"城北的徐公，是齐国的美男子。邹忌不相信自己比徐公美，又问他的妾说："我和徐公谁更美丽？"妾说："徐公怎么能比得上您呢！"第二天，有客人从外面来，和他坐着交谈，问客人说："我和徐公谁更美丽？"客人说："徐公不如您美丽啊。"又过了一天徐公来了，邹忌仔细端详他，自己觉得不如徐公美；再照镜子看看自己，更是觉得差得太远。晚上躺着想这件事，说："我妻子认为我美，是偏爱我；妾认为我美，是害怕我；客人认为我美，是有求于我。"于是上朝拜见齐威王，说："我确实知道自己不如徐公美。我的妻子偏爱我，我的妾害怕我，我的客人有求于我，都说我比徐公美。如今齐国土地方圆千里，有一百二十座城池，宫中的妃子和身边的侍从没有不偏爱大王的，朝廷中的臣子没有不害怕大王的，全国范围内的人没有不有求于大王的：由此看来，大王受蒙蔽很深啦。"齐威王说："好。"就下达命令："大小官吏百姓能够当面指责我过错的，受上等奖赏；上书劝谏我的，受中等奖赏；能够在公共场所批评议论我的过失，传到我耳中的，受下等奖赏。"命令刚下达，群臣都来进谏，门前和院子里像集市一样；几个月以后，还偶尔有人来进谏；一年以后，就是想进言，也没什么可说的了。燕、赵、韩、魏等国听说了这件事，都到齐国来朝见。这就是所谓在朝廷上战胜了敌国。',
