    translation: '陈胜是阳城人，字涉。吴广是阳夏人，字叔。陈涉年轻时，曾经和别人一起被雇佣耕地，他停止耕作走到田埂上，惆怅叹息了很久，说："如果有一天富贵了，不要彼此忘记。"雇工们笑着回答说："你是被雇佣给别人种地的，怎么能富贵呢？"陈涉长叹一声说："唉！燕雀怎么能知道鸿鹄的志向呢！"秦二世元年七月，朝廷征发贫苦老百姓去驻守渔阳，九百人驻扎在大泽乡。陈胜、吴广都被编入谪戍的队伍里，担任屯长。恰逢遇到大雨，道路不通，估计已经误了期限。误了期限，按秦朝的法律都要被斩首。陈胜、吴广于是商量说："现在逃跑也是死，发动起义也是死，同样都是死，为国事而死可以吗？"陈胜说："天下百姓受秦朝统治的逼迫已经很久了。我听说秦二世是小儿子，不应当立为皇帝，应当立为皇帝的是公子扶苏。现在如果把我们的队伍假称是公子扶苏和项燕的队伍，向天下人发出起义的倡导，应该有很多响应的人。"吴广认为这个道理很对。就去占卜。占卜的人知道他们的意图，说："你们的事情都能成功，能建功立业。不过你们把这件事向鬼神问卜一下吧！"陈胜、吴广很高兴，考虑占卜人所说的向鬼神问卜的意思，说："这是教我们先威服众人罢了。"于是用朱砂在丝帛上写"陈胜王"三个字，放在别人用网捕获的鱼的肚子里。士兵买鱼回来烹食，发现鱼肚子里的丝帛，本来就已经觉得奇怪了。陈胜又暗中指使吴广到驻地旁的丛林里的神庙中，夜里用笼子罩着火装作鬼火，像狐狸一样叫喊道："大楚复兴，陈胜为王。"士兵们夜里都很惊恐。第二天，士兵中到处谈论这件事，都指指点点地看着陈胜。',
